import csv, json, os, random, subprocess, tempfile
ns={'__name__':'pd440_test'}
exec(compile(open('/app/driver.py').read(),'/app/driver.py','exec'),ns)
rng=random.Random(440)
for revision in ('C','D'):
 for case in range(200):
  spec={'revision':revision,'cs':rng.randrange(32),'freq_hz':{},'gain':{},'phase_deg':{},'enable':{}}
  for ch in 'ABCD':
   spec['freq_hz'][ch]=rng.randrange(256)
   spec['gain'][ch]=rng.randrange(64)
   spec['phase_deg'][ch]=2*rng.randrange(256)
   spec['enable'][ch]=rng.randrange(2)
  writes=ns['excitation_writes'](spec)
  regs=[0]*16
  for cs,addr,data in writes:
   assert cs==spec['cs'] and 2<=addr<=15 and 0<=data<=65535
   if revision=='D': assert addr!=12
   regs[addr]=data
  for i,ch in enumerate('ABCD'):
   assert regs[2+i*3]&255==spec['freq_hz'][ch]
   assert (regs[4+i*3]&255)*2==spec['phase_deg'][ch]
   gain=regs[3+i*3]&255
   if revision=='D' and i==2: gain=(regs[9]>>8)&255
   if revision=='D' and i==3: gain=regs[9]&255
   assert gain==spec['gain'][ch]
   assert (regs[14]>>i)&1==spec['enable'][ch]
  assert regs[14]&240==0
print('400 independent excitation replays passed, both revisions')
for key,value in [('phase_deg',91),('freq_hz',256),('gain',64),('enable',2)]:
 spec=json.load(open('/app/excitation_spec.json'));spec[key]['A']=value
 try: ns['excitation_writes'](spec)
 except ValueError: pass
 else: raise AssertionError(key)
print('Unrepresentable input validation passed')
with tempfile.TemporaryDirectory(prefix='pd440-test-') as temp:
 original=[json.loads(s) for s in open('/tmp/pd440-decode.jsonl')]
 mapping={0:93,1:4,2:71,3:0}
 bus=os.path.join(temp,'bus.csv');strain=os.path.join(temp,'strain.csv')
 with open('/app/captures/site_a/bus.csv') as src,open(bus,'w',newline='') as dst:
  reader=csv.reader(src);writer=csv.writer(dst);writer.writerow(next(reader))
  for t,cs,op,addr,data in reader:
   if addr=='0x00':data='0x53FF'
   writer.writerow([int(t)*2+987654321,mapping[int(cs)],op,addr,data])
 with open('/app/captures/site_a/strain.csv') as src,open(strain,'w',newline='') as dst:
  reader=csv.reader(src);writer=csv.writer(dst);writer.writerow(next(reader))
  for t,adc in reader:writer.writerow([round(int(t)*1.3)-86543210,int(adc)*3+125])
 outputs=[]
 for run in range(2):
  out=os.path.join(temp,str(run)+'.jsonl')
  subprocess.run(['python3','/app/driver.py','decode','--capture',bus,'--strain',strain,'--out',out],check=True)
  outputs.append(open(out,'rb').read())
 assert outputs[0]==outputs[1]
 modified=[json.loads(line) for line in outputs[0].splitlines()]
 assert len(modified)==len(original)==236
 for before,after in zip(original,modified):
  assert after['cs']==mapping[before['cs']]
  assert after['t_us']==before['t_us']*2+987654321
  assert after['revision']==before['revision']
  assert after['addr']==before['addr'] and after['op']==before['op']
  if before['addr']!=0:assert after['fields']==before['fields']
print('Decode invariant under chip-select renaming, identical IDs, independent clock offsets/rates, and ADC calibration; byte determinism passed')
for revision in ('C','D'):
 for addr in range(16,256):assert ns['fields'](revision,addr,65535)=={}
assert ns['fields']('D',12,65535)=={}
assert ns['fields']('C',12,65535)=={'D_GAIN':255}
assert ns['fields']('D',9,0xABCD)=={'C_GAIN':0xAB,'D_GAIN':0xCD}
print('Reserved, vacant, and packed field decoding passed')
